def records(text):
    results = []
    for line in text.splitlines():
        if not line.strip():
            continue
        obj = {}
        for part in line.split(","):
            part = part.strip()
            if not part:
                continue
            key, _, value = part.partition(":")
            obj[key.strip()] = value.strip()
        results.append(obj)
    return results

